head.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name:     Solidarity (union & association theme)
Version:  1.0.0
Based on: BCorporate v3 layout, rebuilt dependency-free
----------------------------------------------- */

/* Variable definitions (editable in Theme > Customise > Advanced)
====================
<Variable name="primary.color" description="Primary (top bar, hero, footer)" type="color" default="#13294B" value="#13294B"/>
<Variable name="primary.dark.color" description="Primary, darker shade" type="color" default="#0B1A33" value="#0B1A33"/>
<Variable name="accent.color" description="Accent (buttons, highlights)" type="color" default="#C8102E" value="#C8102E"/>
<Variable name="accent.dark.color" description="Accent hover" type="color" default="#9E0C23" value="#9E0C23"/>
<Variable name="highlight.color" description="Small highlights on dark backgrounds" type="color" default="#F2B705" value="#F2B705"/>
<Variable name="page.background.color" description="Page background" type="color" default="#F4F6FA" value="#F4F6FA"/>
<Variable name="band.background.color" description="Alternate section background" type="color" default="#EAEEF4" value="#EAEEF4"/>
<Variable name="text.color" description="Body text" type="color" default="#1B2533" value="#1B2533"/>
<Variable name="muted.color" description="Muted text" type="color" default="#5B6778" value="#5B6778"/>
<Variable name="border.color" description="Borders and dividers" type="color" default="#DCE1EA" value="#DCE1EA"/>
*/



/* ---------- Base ---------- */
*, *::before, *::after { box-sizing: border-box; }
html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
  scroll-padding-top: calc(76px + 12px);
}
body {
  margin: 0;
  font-family: 'Open Sans', Arial, Helvetica, sans-serif;
  font-size: 16px;
  line-height: 1.65;
  color: $(text.color);
  background: $(page.background.color);
  -webkit-font-smoothing: antialiased;
  /* clip (not hidden): stops sideways scrolling without turning <body> into a scroll box,
     which would break the sticky header (hidden is the fallback for old browsers) */
  overflow-x: hidden;
  overflow-x: clip;
}
/* Menu open: stop the page scrolling behind it. Only <html>: locking <body> too would unstick the header */
html.nav-locked { overflow: hidden; }
img, video, iframe, embed, object { max-width: 100%; }
img { height: auto; border: 0; }
a { color: inherit; text-decoration: none; }
p { margin: 0 0 1em; }
h1, h2, h3, h4, h5, h6 { margin: 0 0 0.5em; line-height: 1.2; color: inherit; }
button, input, select, textarea { font: inherit; color: inherit; }
[hidden] { display: none !important; }
/* "body" prefix: Blogger injects its own widget stylesheet, sometimes after this skin */
body .section, body .widget { margin: 0; padding: 0; }
body .widget ul, body .widget ol { list-style: none; margin: 0; padding: 0; }
body .widget li { margin: 0; padding: 0; }
body .widget .post-body ul { list-style: disc; padding-left: 1.4em; margin: 0 0 1.2em; }
body .widget .post-body ol { list-style: decimal; padding-left: 1.4em; margin: 0 0 1.2em; }
body .widget .post-body li { padding: 0.15em 0; }
.navbar, #navbar, #navbar-iframe { display: none !important; height: 0 !important; }
:focus-visible { outline: 3px solid $(highlight.color); outline-offset: 3px; }

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 16px;
}
@media (min-width: 768px) { .container { padding: 0 28px; } }

.skip-link {
  position: absolute;
  left: -9999px;
  top: 12px;
  z-index: 300;
  background: #fff;
  color: $(primary.color);
  font-weight: 700;
  padding: 10px 16px;
  border-radius: 6px;
}
.skip-link:focus { left: 16px; }

/* ---------- Buttons and badges ---------- */
.btn,
.header-cta .widget-content a,
.hero-actions a,
.cta-body li a,
.join-card a,
.sidebar .btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 46px;
  padding: 12px 24px;
  border: 2px solid transparent;
  border-radius: 6px;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  text-align: center;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, color 0.2s, transform 0.2s;
}
.btn-primary,
.header-cta .widget-content a,
.hero-actions li:first-child a,
.cta-body li:first-child a,
.join-card a,
.sidebar .btn {
  background: $(accent.color);
  border-color: $(accent.color);
  color: #fff;
}
.btn-primary:hover,
.header-cta .widget-content a:hover,
.hero-actions li:first-child a:hover,
.cta-body li:first-child a:hover,
.join-card a:hover,
.sidebar .btn:hover {
  background: $(accent.dark.color);
  border-color: $(accent.dark.color);
  color: #fff;
  transform: translateY(-1px);
}
.hero-actions li a,
.cta-body li a {
  background: transparent;
  border-color: rgba(255, 255, 255, 0.5);
  color: #fff;
}
.hero-actions li a:hover,
.cta-body li a:hover { border-color: #fff; background: rgba(255, 255, 255, 0.08); }
.btn-outline {
  background: #fff;
  border-color: $(border.color);
  color: $(primary.color);
}
.btn-outline:hover { border-color: $(primary.color); }

.badge {
  display: inline-block;
  background: $(accent.color);
  color: #fff;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.8px;
  line-height: 1;
  text-transform: uppercase;
  padding: 5px 8px 6px;
  border-radius: 3px;
  transition: background 0.2s, color 0.2s;
}
a.badge:hover { background: $(primary.color); color: #fff; }
.badge-soft { background: $(band.background.color); color: $(primary.color); }
a.badge-soft:hover { background: $(accent.color); color: #fff; }

/* ---------- Top bar ---------- */
.topbar {
  background: $(primary.dark.color);
  color: #D5DDE8;
  font-size: 13px;
}
.topbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 44px;
}
.topbar-social h2, .topbar-lang h2 { display: none; }
.topbar-social { flex: 0 1 auto; min-width: 0; }
body .topbar-lang { margin-left: auto; } /* "body": beats Blogger's injected .section margin */
.lang-picker { position: relative; }
.lang-toggle {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 34px;
  padding: 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
.lang-toggle:hover, .lang-picker.is-open .lang-toggle { background: $(accent.color); border-color: $(accent.color); }
.lang-toggle::after {
  content: '';
  width: 6px;
  height: 6px;
  margin: -3px 0 0 2px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: rotate(45deg);
}
.lang-menu {
  position: absolute;
  right: 0;
  top: calc(100% + 8px);
  z-index: 150;
  min-width: 190px;
  max-height: 70vh;
  overflow-y: auto;
  padding: 6px 0;
  background: #fff;
  border-radius: 6px;
  border-top: 3px solid $(accent.color);
  box-shadow: 0 14px 34px rgba(15, 30, 55, 0.16);
  display: none;
}
.lang-picker.is-open .lang-menu { display: block; }
.lang-menu a { display: block; padding: 9px 16px; font-size: 14px; color: $(text.color); }
.lang-menu a:hover { background: $(page.background.color); color: $(accent.color); }
.lang-menu a[aria-current='true'] { font-weight: 700; color: $(accent.color); }
.lang-menu a[aria-current='true']::after { content: ' \2713'; }
/* Google Translate: hide its top banner, tooltips and highlight so the design stays intact */
iframe.goog-te-banner-frame, .goog-te-banner-frame, iframe.VIpgJd-ZVi9od-ORHb-OEVmcd,
#goog-gt-tt, .goog-te-balloon-frame, .VIpgJd-yAWNEb-L7lbkb { display: none !important; }
body { top: 0 !important; }
.goog-text-highlight { background: none !important; box-shadow: none !important; }
.social-list,
.topbar-social .widget-content ul {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
}
.topbar-social .widget-content a,
.footer-social a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  color: #D5DDE8;
  transition: background 0.2s, color 0.2s;
}
.topbar-social .widget-content a:hover,
.footer-social a:hover { background: $(accent.color); color: #fff; }
.social-icon { display: block; width: 16px; height: 16px; fill: currentColor; }
.has-icon .social-text {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.search-form {
  display: flex;
  align-items: stretch;
  max-width: 100%;
  background: #fff;
  border: 1px solid $(border.color);
  border-radius: 999px;
  overflow: hidden;
}
.search-form input {
  flex: 1 1 auto;
  min-width: 0;
  border: 0;
  background: transparent;
  padding: 8px 14px;
  color: $(text.color);
  outline: none;
}
.search-form button {
  flex: 0 0 auto;
  border: 0;
  background: $(accent.color);
  color: #fff;
  width: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.search-form button:hover { background: $(accent.dark.color); }
.topbar-search {
  flex: 0 1 280px;
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.18);
}
.topbar-search input { color: #fff; padding: 6px 14px; font-size: 13px; }
.topbar-search input::placeholder { color: #9AA8BC; }
.topbar-search button { width: 36px; }

/* ---------- Header ---------- */
.site-header {
  position: -webkit-sticky;
  position: sticky;
  top: 0;
  z-index: 100;
  background: #fff;
  border-bottom: 4px solid $(accent.color);
  transition: box-shadow 0.2s;
}
.site-header.is-scrolled { box-shadow: 0 6px 22px rgba(15, 30, 55, 0.14); }
.header-inner {
  position: relative;
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 76px;
}
.brand-section { flex: 1 1 auto; min-width: 0; }
.brand { display: flex; align-items: center; gap: 12px; color: $(primary.color); padding: 8px 0; }
.brand-mark {
  flex: 0 0 48px;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: $(accent.color);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 0.5px;
  overflow: hidden;
}
.brand-mark img { width: 100%; height: 100%; object-fit: cover; }
.brand-logo img { display: block; max-height: 60px; width: auto; }
.brand-text { display: flex; flex-direction: column; min-width: 0; }
.brand-name {
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: 0.3px;
  text-transform: uppercase;
  color: $(primary.color);
}
.brand-tagline { font-size: 12px; color: $(muted.color); line-height: 1.3; }

.nav-toggle {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  border: 0;
  border-radius: 6px;
  background: $(primary.color);
  color: #fff;
  cursor: pointer;
}
.nav-toggle .icon-close { display: none; }
.nav-open .nav-toggle .icon-menu { display: none; }
.nav-open .nav-toggle .icon-close { display: block; }

/* Mobile drawer */
.nav-drawer {
  position: fixed;
  left: 0;
  right: 0;
  top: 120px;
  bottom: 0;
  z-index: 99;
  background: #fff;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 8px 16px 32px;
  display: none;
  border-top: 1px solid $(border.color);
  overscroll-behavior: contain;
}
.nav-open .nav-drawer { display: block; }
.site-nav .widget-content > ul > li { border-bottom: 1px solid $(border.color); position: relative; }
.site-nav .widget-content a {
  display: block;
  padding: 14px 48px 14px 4px;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: 17px;
  font-weight: 500;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: $(primary.color);
}
.site-nav .widget-content a:hover { color: $(accent.color); }
.site-nav .widget-content ul ul { display: none; padding: 0 0 10px 12px; border-left: 3px solid $(accent.color); margin-left: 4px; }
.site-nav .widget-content li.sub-open > ul { display: block; }
.site-nav .widget-content ul ul a {
  font-family: 'Open Sans', Arial, Helvetica, sans-serif;
  font-size: 15px;
  font-weight: 400;
  text-transform: none;
  letter-spacing: 0;
  padding: 9px 8px;
  color: $(text.color);
}
.sub-toggle {
  position: absolute;
  top: 6px;
  right: 0;
  width: 42px;
  height: 42px;
  border: 0;
  background: transparent;
  color: $(primary.color);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}
.sub-toggle svg { transition: transform 0.2s; }
.sub-open > .sub-toggle svg { transform: rotate(180deg); }
.header-cta { margin-top: 20px; }
.header-cta .widget-content a { width: 100%; }

@media (min-width: 1100px) {
  .nav-toggle { display: none; }
  .header-inner { flex-wrap: wrap; column-gap: 24px; row-gap: 0; }
  /* The drawer's two sections become items of the header row: Join top right, menu on its own row */
  .nav-drawer { display: contents !important; }
  .header-cta { order: 2; }
  .site-nav { order: 3; flex: 1 0 100%; border-top: 1px solid $(border.color); }
  .site-nav .widget-content > ul { display: flex; flex-wrap: wrap; align-items: center; margin-left: -14px; }
  .site-nav .widget-content > ul > li { border: 0; }
  .site-nav .widget-content > ul > li > a {
    padding: 15px 14px;
    font-size: 15px;
    white-space: nowrap;
    position: relative;
  }
  .site-nav .widget-content > ul > li > a::after {
    content: '';
    position: absolute;
    left: 14px;
    right: 14px;
    bottom: 0;
    height: 3px;
    background: $(accent.color);
    transform: scaleX(0);
    transition: transform 0.2s;
  }
  .site-nav .widget-content > ul > li:hover > a::after,
  .site-nav .widget-content > ul > li:focus-within > a::after { transform: scaleX(1); }
  .site-nav .widget-content > ul > li.has-sub > a { padding-right: 28px; }
  .site-nav .widget-content > ul > li.has-sub > a::before {
    content: '';
    position: absolute;
    right: 12px;
    top: 50%;
    margin-top: -6px;
    width: 6px;
    height: 6px;
    border-right: 2px solid currentColor;
    border-bottom: 2px solid currentColor;
    transform: rotate(45deg);
  }
  .sub-toggle { display: none; }
  .site-nav .widget-content ul ul {
    display: block;
    position: absolute;
    top: 100%;
    left: 0;
    min-width: 250px;
    max-height: 70vh;
    overflow-y: auto;
    margin: 0;
    padding: 8px 0;
    background: #fff;
    border: 0;
    border-top: 3px solid $(accent.color);
    border-radius: 0 0 6px 6px;
    box-shadow: 0 14px 34px rgba(15, 30, 55, 0.16);
    opacity: 0;
    visibility: hidden;
    transform: translateY(8px);
    transition: opacity 0.18s, transform 0.18s, visibility 0.18s;
    z-index: 120;
  }
  /* Dropdowns near the right edge open leftwards (set by theme.js) */
  .site-nav .widget-content li.drop-left > ul { left: auto; right: 0; }
  .site-nav .widget-content li:hover > ul,
  .site-nav .widget-content li:focus-within > ul {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
  }
  .site-nav .widget-content ul ul a { padding: 9px 18px; font-size: 14px; }
  .site-nav .widget-content ul ul a:hover { background: $(page.background.color); color: $(accent.color); }
  .header-cta { margin: 0; }
  .header-cta .widget-content a { width: auto; min-height: 42px; padding: 10px 18px; font-size: 15px; }
}

/* ---------- Homepage-only sections ---------- */
.home-only { display: none; }

/* ---------- Ticker ---------- */
.ticker { background: #fff; border-bottom: 1px solid $(border.color); }
.ticker-inner { display: flex; align-items: stretch; gap: 14px; min-height: 46px; }
.ticker-label {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  background: $(accent.color);
  color: #fff;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 1px;
  text-transform: uppercase;
  padding: 0 14px;
}
.ticker-track {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  display: flex;
  align-items: center;
  -webkit-mask-image: linear-gradient(to right, transparent, #000 24px, #000 calc(100% - 24px), transparent);
  mask-image: linear-gradient(to right, transparent, #000 24px, #000 calc(100% - 24px), transparent);
}
.ticker-list {
  display: flex;
  gap: 36px;
  margin: 0;
  padding: 0;
  list-style: none;
  white-space: nowrap;
  animation: ticker 60s linear infinite;
}
.ticker-track:hover .ticker-list,
.ticker-track:focus-within .ticker-list { animation-play-state: paused; }
.ticker-list li { flex: 0 0 auto; }
.ticker-list a { font-size: 14px; font-weight: 600; color: $(primary.color); }
.ticker-list a:hover { color: $(accent.color); }
.ticker-list a::before { content: '\25A0'; color: $(accent.color); font-size: 9px; margin-right: 10px; vertical-align: 2px; }
@keyframes ticker { from { transform: translateX(0); } to { transform: translateX(-50%); } }
@media (prefers-reduced-motion: reduce) {
  .ticker-list { animation: none; }
  .ticker-track { overflow-x: auto; }
}

/* ---------- Hero ---------- */
.hero {
  position: relative;
  background-color: $(primary.color);
  background-image: repeating-linear-gradient(135deg, rgba(255, 255, 255, 0.035) 0, rgba(255, 255, 255, 0.035) 2px, transparent 2px, transparent 22px);
  color: #fff;
  overflow: hidden;
}
.hero::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 6px;
  background: $(accent.color);
}
.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 32px;
  padding-top: 44px;
  padding-bottom: 56px;
  align-items: center;
}
.hero-copy { position: relative; }
.hero-eyebrow {
  display: inline-block;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: $(highlight.color);
  margin-bottom: 14px;
}
.hero-eyebrow::before {
  content: '';
  display: inline-block;
  width: 28px;
  height: 3px;
  background: $(accent.color);
  vertical-align: middle;
  margin: -3px 10px 0 0;
}
.hero-title {
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-weight: 700;
  font-size: clamp(32px, 6.2vw, 58px);
  line-height: 1.05;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  margin: 0 0 18px;
  color: #fff;
}
.hero-title .accent { color: $(highlight.color); }
.hero-text { font-size: 18px; line-height: 1.6; color: #D5DDE8; max-width: 560px; }
.hero-text p:last-child { margin-bottom: 0; }
.hero-actions { margin-top: 26px; }
.hero-actions ul { display: flex; flex-wrap: wrap; gap: 12px; }
.hero-media {
  position: relative;
  border-radius: 10px;
  overflow: hidden;
  background: $(primary.dark.color);
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.35);
  aspect-ratio: 16 / 9;
}
.hero-media img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  opacity: 0;
  transition: opacity 0.8s ease;
}
.hero-media img:first-child,
.hero-media img.is-active { opacity: 1; }
.hero-media.is-slideshow img:first-child:not(.is-active) { opacity: 0; }
.slide-dots {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 10px;
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 6px;
  padding: 0 52px;
  z-index: 2;
}
/* Each dot is a 24px tap area around a small visible dot */
.slide-dots { gap: 0; }
.slide-dots button {
  position: relative;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: pointer;
}
.slide-dots button::before {
  content: '';
  position: absolute;
  left: 7px;
  top: 7px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.5);
  transition: transform 0.2s, background 0.2s;
}
.slide-dots button[aria-current='true']::before { background: $(accent.color); transform: scale(1.25); }
.slide-btn {
  position: absolute;
  top: 50%;
  z-index: 2;
  width: 40px;
  height: 40px;
  margin-top: -20px;
  border: 0;
  border-radius: 50%;
  background: rgba(11, 26, 51, 0.6);
  color: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}
.slide-btn:hover { background: $(accent.color); }
.slide-prev { left: 10px; }
.slide-next { right: 10px; }
.hero-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 24px;
  text-align: center;
  background: radial-gradient(circle at 30% 20%, rgba(255, 255, 255, 0.12), transparent 60%), $(accent.color);
}
.hero-placeholder strong {
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: clamp(28px, 4vw, 44px);
  text-transform: uppercase;
  letter-spacing: 1px;
}
.hero-placeholder span { max-width: 380px; font-size: 14px; color: rgba(255, 255, 255, 0.85); }
@media (min-width: 960px) {
  .hero-grid { grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); gap: 48px; padding-top: 64px; padding-bottom: 76px; }
}

/* ---------- Bands and section headings ---------- */
.band { padding: 48px 0; }
@media (min-width: 768px) { .band { padding: 64px 0; } }
.band h2.title,
.feed-head h2.title,
.section-title,
.related-title {
  position: relative;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-weight: 600;
  font-size: clamp(24px, 3.4vw, 32px);
  line-height: 1.15;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: $(primary.color);
  margin: 0 0 24px;
  padding-bottom: 12px;
}
.band h2.title::after,
.feed-head h2.title::after,
.section-title::after,
.related-title::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: 0;
  width: 56px;
  height: 4px;
  background: $(accent.color);
}
.band-services h2.title,
.band-stats h2.title,
.band-partners h2.title,
.band-about .feed-head h2.title { text-align: center; }
.band-services h2.title::after,
.band-stats h2.title::after,
.band-partners h2.title::after,
.band-about .feed-head h2.title::after { left: 50%; margin-left: -28px; }

/* What we do */
.band-services { background: #fff; }
.band-services .widget-content > p { max-width: 720px; margin: 0 auto 28px; text-align: center; color: $(muted.color); }
.band-services .widget-content ul {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 18px;
  counter-reset: service;
}
.band-services .widget-content li {
  position: relative;
  background: $(page.background.color);
  border-radius: 10px;
  padding: 26px 22px 24px;
  border-top: 4px solid $(primary.color);
  color: $(muted.color);
  font-size: 15px;
  transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
}
.band-services .widget-content li:hover { transform: translateY(-3px); box-shadow: 0 14px 34px rgba(15, 30, 55, 0.16); border-top-color: $(accent.color); }
.band-services .widget-content li::before {
  counter-increment: service;
  content: counter(service, decimal-leading-zero);
  display: block;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: 34px;
  font-weight: 700;
  line-height: 1;
  color: $(accent.color);
  margin-bottom: 12px;
}
.band-services .widget-content li strong {
  display: block;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: 0.3px;
  text-transform: uppercase;
  color: $(primary.color);
  margin-bottom: 6px;
}
@media (min-width: 640px) { .band-services .widget-content ul { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1024px) { .band-services .widget-content ul { grid-template-columns: repeat(4, minmax(0, 1fr)); } }

/* Numbers */
.band-stats {
  background: $(accent.color);
  color: #fff;
  padding: 40px 0;
}
.band-stats h2.title { color: #fff; }
.band-stats h2.title::after { background: #fff; }
.band-stats .widget-content ul {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
  text-align: center;
}
.band-stats .widget-content li { font-size: 14px; letter-spacing: 1px; text-transform: uppercase; color: rgba(255, 255, 255, 0.85); }
.band-stats .widget-content li strong {
  display: block;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: clamp(34px, 5vw, 50px);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: 0;
  color: #fff;
}
@media (min-width: 768px) { .band-stats .widget-content ul { grid-template-columns: repeat(4, minmax(0, 1fr)); } }

/* ---------- Label feeds ---------- */
.feed-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 0 12px; margin-bottom: 20px; }
.feed-head h2.title { margin: 0; min-width: 0; overflow-wrap: break-word; }
.feed-more {
  flex: 0 0 auto;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: $(accent.color);
  padding-bottom: 14px;
}
.feed-more::after { content: ' \2192'; }
.feed-more:hover { color: $(primary.color); }
.feed-status { color: $(muted.color); font-size: 14px; }
.feed-row .feed-head h2.title { font-size: clamp(22px, 2.4vw, 26px); }
.feed-row { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px; }
@media (min-width: 768px) { .feed-row { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1024px) { .feed-row { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 28px; } }

.feed-thumb {
  display: block;
  position: relative;
  aspect-ratio: 16 / 9;
  background: $(band.background.color);
  border-radius: 6px;
  overflow: hidden;
}
.feed-thumb img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; transition: transform 0.4s; }
a.feed-thumb:hover img,
.feed-featured:hover .feed-thumb img { transform: scale(1.04); }
.feed-thumb-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  background: $(primary.color);
  color: rgba(255, 255, 255, 0.4);
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: 28px;
  text-transform: uppercase;
}
.feed-date { display: block; font-size: 12px; font-weight: 600; letter-spacing: 0.5px; text-transform: uppercase; color: $(accent.color); }
.feed-title { font-family: 'Open Sans', Arial, Helvetica, sans-serif; font-weight: 700; font-size: 16px; line-height: 1.35; color: $(primary.color); margin: 4px 0 0; }
.feed-title a:hover { color: $(accent.color); }

/* kind: news (first post large, then a list) */
.feed-featured { margin-bottom: 14px; }
.feed-featured .feed-body { padding-top: 12px; }
.feed-featured .feed-title { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif; font-weight: 600; font-size: 21px; line-height: 1.2; }
.feed-featured .feed-excerpt { font-size: 14px; color: $(muted.color); margin: 8px 0 0; }
.feed-block .feed-list > li { display: flex; align-items: flex-start; gap: 12px; padding: 12px 0; border-top: 1px solid $(border.color); }
.feed-list .feed-thumb { flex: 0 0 92px; width: 92px; aspect-ratio: 4 / 3; }
.feed-list .feed-title { font-size: 15px; }

/* kind: message (leader's message) */
.band-leader { background: $(band.background.color); }
.leader-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 44px; }
@media (min-width: 1024px) { .leader-grid { grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: 40px; } }
.feed-message {
  background: #fff;
  border-radius: 10px;
  box-shadow: 0 2px 14px rgba(15, 30, 55, 0.08);
  overflow: hidden;
}
.feed-message .feed-thumb { border-radius: 0; aspect-ratio: 4 / 3; }
.feed-message .feed-thumb img { object-fit: cover; object-position: top center; }
.feed-message .feed-body { position: relative; padding: 24px 24px 26px; }
.feed-message .feed-body::before {
  content: '\201C';
  position: absolute;
  top: -38px;
  right: 18px;
  font-family: Georgia, serif;
  font-size: 110px;
  line-height: 1;
  color: $(accent.color);
}
.feed-message .feed-title { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif; font-size: 22px; font-weight: 600; line-height: 1.2; }
.feed-message .feed-excerpt { font-size: 15px; color: $(muted.color); font-style: italic; margin: 10px 0 16px; }
.feed-readmore { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif; font-weight: 500; letter-spacing: 0.6px; text-transform: uppercase; font-size: 14px; color: $(accent.color); }
.feed-readmore::after { content: ' \2192'; }

/* kind: tiles (events) */
.feed-tiles { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
@media (min-width: 640px) { .feed-tiles { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.feed-tile { position: relative; display: block; border-radius: 6px; overflow: hidden; background: $(primary.color); aspect-ratio: 1 / 1; }
.feed-tile .feed-thumb { position: absolute; inset: 0; aspect-ratio: auto; border-radius: 0; }
.feed-tile-text {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 36px 12px 12px;
  background: linear-gradient(to top, rgba(8, 18, 36, 0.92), rgba(8, 18, 36, 0));
  color: #fff;
}
.feed-tile .feed-date { color: $(highlight.color); font-size: 11px; }
.feed-tile .feed-title { color: #fff; font-size: 14px; line-height: 1.3; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.feed-tile:hover img { transform: scale(1.06); }

/* kind: list (about) */
.band-about { background: #fff; }
.band-about .feed-head { flex-direction: column; align-items: center; }
.band-about .feed-more { padding-bottom: 0; }
.feed-cards { display: grid; grid-template-columns: minmax(0, 1fr); gap: 18px; }
@media (min-width: 640px) { .feed-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1024px) { .feed-cards { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.feed-card { background: $(page.background.color); border-radius: 10px; overflow: hidden; transition: transform 0.2s, box-shadow 0.2s; }
.feed-card:hover { transform: translateY(-3px); box-shadow: 0 14px 34px rgba(15, 30, 55, 0.16); }
.feed-card .feed-thumb { border-radius: 0; }
.feed-card .feed-body { padding: 14px 16px 18px; }

/* kind: strip (member institutions / branches) */
.band-members { background: $(band.background.color); }
.strip-wrap { position: relative; }
.feed-strip {
  display: flex;
  gap: 14px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  padding-bottom: 10px;
  scrollbar-width: thin;
}
.feed-strip > li { flex: 0 0 72%; scroll-snap-align: start; }
@media (min-width: 640px) { .feed-strip > li { flex-basis: 40%; } }
@media (min-width: 1024px) { .feed-strip > li { flex-basis: calc((100% - 56px) / 5); } }
.feed-strip .feed-card { background: #fff; height: 100%; }
.feed-strip .feed-title { font-size: 14px; }
.strip-btn {
  position: absolute;
  top: 34%;
  z-index: 2;
  width: 40px;
  height: 40px;
  border: 0;
  border-radius: 50%;
  background: $(primary.color);
  color: #fff;
  box-shadow: 0 2px 14px rgba(15, 30, 55, 0.08);
  cursor: pointer;
  display: none;
  align-items: center;
  justify-content: center;
}
.strip-btn:hover { background: $(accent.color); }
.strip-prev { left: -12px; }
.strip-next { right: -12px; }
@media (min-width: 768px) { .strip-btn { display: flex; } }

/* ---------- Join call-to-action ---------- */
.band-cta {
  background-color: $(primary.color);
  background-image: repeating-linear-gradient(135deg, rgba(255, 255, 255, 0.035) 0, rgba(255, 255, 255, 0.035) 2px, transparent 2px, transparent 22px);
  color: #fff;
  text-align: center;
}
.cta-inner { max-width: 760px; margin: 0 auto; }
.cta-title {
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-weight: 700;
  font-size: clamp(30px, 5vw, 46px);
  line-height: 1.1;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #fff;
  margin: 0 0 14px;
}
.cta-title::after { content: ''; display: block; width: 64px; height: 4px; margin: 16px auto 0; background: $(accent.color); }
.cta-body p { font-size: 18px; color: #D5DDE8; }
.cta-body ul { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; margin-top: 22px; }

/* ---------- Partners ---------- */
.band-partners { background: #fff; padding: 44px 0; }
.logo-list { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 18px 36px; }
.logo-list li { display: flex; align-items: center; justify-content: center; }
.logo-list img {
  display: block;
  max-height: 64px;
  max-width: 150px;
  width: auto;
  filter: grayscale(1);
  opacity: 0.75;
  transition: filter 0.2s, opacity 0.2s;
}
.logo-list li:hover img { filter: none; opacity: 1; }
.logo-placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 140px;
  height: 60px;
  border: 2px dashed $(border.color);
  border-radius: 6px;
  font-size: 12px;
  color: $(muted.color);
  text-transform: uppercase;
  letter-spacing: 1px;
}

/* ---------- Important documents (download cards) ---------- */
.band-downloads { background: $(band.background.color); }
.band-downloads h2.title { text-align: center; }
.band-downloads h2.title::after { left: 50%; margin-left: -28px; }
.doc-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; }
@media (min-width: 640px) { .doc-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1024px) { .band-downloads .doc-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.doc-card {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr);
  grid-template-rows: auto 1fr;
  gap: 4px 14px;
  padding: 18px;
  background: #fff;
  border-radius: 10px;
  box-shadow: 0 2px 14px rgba(15, 30, 55, 0.08);
  transition: transform 0.2s, box-shadow 0.2s;
}
.doc-card:hover { transform: translateY(-2px); box-shadow: 0 14px 34px rgba(15, 30, 55, 0.16); }
.doc-icon {
  grid-row: 1 / 3;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  width: 52px;
  height: 64px;
  padding-bottom: 9px;
  border-radius: 4px 14px 4px 4px;
  background: $(primary.color);
  color: #fff;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.6px;
}
.doc-pdf .doc-icon { background: #C8102E; }
.doc-word .doc-icon { background: #2B579A; }
.doc-excel .doc-icon { background: #217346; }
.doc-powerpoint .doc-icon { background: #C4471D; }
.doc-zip .doc-icon { background: #6B4E71; }
.doc-image .doc-icon { background: #0F7C8C; }
.doc-title { font-family: 'Open Sans', Arial, Helvetica, sans-serif; font-size: 16px; font-weight: 700; line-height: 1.35; color: $(primary.color); margin: 0; overflow-wrap: break-word; }
.doc-desc { font-size: 14px; line-height: 1.5; color: $(muted.color); margin: 4px 0 0; }
.doc-actions { grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
.doc-actions .btn { min-height: 42px; padding: 9px 18px; font-size: 15px; }
.doc-actions .doc-download { flex: 1 1 auto; }
.doc-actions .social-icon { width: 18px; height: 18px; }
.doc-more { text-align: center; margin: 26px 0 0; }
.post-body .doc-grid { margin: 1.2em 0; }
.post-body .doc-card a { color: inherit !important; text-decoration: none; }
.post-body .doc-actions .btn-primary { color: #fff !important; }
.post-body .doc-actions .btn-outline { color: $(primary.color) !important; }
.post-body .doc-title { margin: 0 !important; font-family: 'Open Sans', Arial, Helvetica, sans-serif !important; font-size: 16px !important; color: $(primary.color) !important; }
/* Inside pages the "consistent text" reset applies, so the cards' own styles are restated firmly */
.post-body .doc-icon { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif !important; font-size: 13px !important; color: #fff !important; background-color: $(primary.color) !important; }
.post-body .doc-pdf .doc-icon { background-color: #C8102E !important; }
.post-body .doc-word .doc-icon { background-color: #2B579A !important; }
.post-body .doc-excel .doc-icon { background-color: #217346 !important; }
.post-body .doc-powerpoint .doc-icon { background-color: #C4471D !important; }
.post-body .doc-zip .doc-icon { background-color: #6B4E71 !important; }
.post-body .doc-image .doc-icon { background-color: #0F7C8C !important; }
.post-body .doc-desc { font-size: 14px !important; line-height: 1.5 !important; color: $(muted.color) !important; }
.post-body .doc-actions .btn { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif !important; font-size: 15px !important; line-height: 1.1 !important; letter-spacing: 0.6px !important; }
.post-body .sitemap-topics .badge { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif !important; font-size: 12px !important; letter-spacing: 0.8px !important; line-height: 1 !important; }
.post-body .sitemap-summary { color: $(muted.color) !important; }

/* ---------- Article presentation: byline, reading time, intro, contents, author box ---------- */
.guest-byline a, .guest-byline strong { color: $(primary.color); font-weight: 700; }
.guest-byline a:hover { color: $(accent.color); }
.guest-role { font-weight: 400; color: $(muted.color); }
.reading-time { white-space: nowrap; }
.post-body .lead-para {
  font-size: 20px !important;
  line-height: 1.6 !important;
  color: $(primary.color) !important;
  margin-bottom: 1.2em;
}
@media (max-width: 639px) { .post-body .lead-para { font-size: 18px !important; } }
.toc {
  margin: 0 0 26px;
  padding: 16px 20px;
  background: $(page.background.color);
  border: 1px solid $(border.color);
  border-radius: 6px;
}
.toc-title { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif; font-size: 15px; font-weight: 600; letter-spacing: 1px; text-transform: uppercase; color: $(accent.color); margin: 0 0 8px; }
body .widget .toc-list { list-style: decimal; padding-left: 1.4em; margin: 0; }
body .widget .toc-list li { padding: 3px 0; }
.toc-list li.toc-sub { list-style: circle; margin-left: 1.2em; font-size: 15px; }
.toc-list a { color: $(primary.color); font-weight: 600; }
.toc-list a:hover { color: $(accent.color); text-decoration: underline; }
.post-body h2[id], .post-body h3[id] { scroll-margin-top: 150px; }
.author-box {
  display: flex;
  gap: 18px;
  align-items: flex-start;
  margin-top: 30px;
  padding: 22px;
  background: $(page.background.color);
  border-radius: 10px;
  border-top: 4px solid $(accent.color);
}
.author-photo {
  flex: 0 0 84px;
  width: 84px;
  height: 84px;
  border-radius: 50%;
  object-fit: cover;
  background: $(band.background.color);
}
.author-initials {
  display: flex;
  align-items: center;
  justify-content: center;
  background: $(primary.color);
  color: #fff;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: 30px;
  font-weight: 600;
}
.author-text { min-width: 0; }
.author-text p { margin: 0; }
.author-eyebrow { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif; font-size: 13px; letter-spacing: 1.2px; text-transform: uppercase; color: $(accent.color); }
.author-name { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif; font-size: 22px; font-weight: 600; color: $(primary.color); margin-top: 2px !important; }
.author-name a:hover { color: $(accent.color); }
.author-role { font-size: 14px; color: $(muted.color); font-weight: 600; }
.author-bio { font-size: 15px; line-height: 1.6; margin-top: 8px !important; }
.author-more { display: inline-block; margin-top: 10px; font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif; font-size: 14px; letter-spacing: 0.6px; text-transform: uppercase; color: $(accent.color); }
.author-more::after { content: ' \2192'; }
@media (max-width: 479px) {
  .author-box { flex-direction: column; align-items: center; text-align: center; }
}

/* ---------- Branch offices ---------- */
.branch-filter { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin: 0 0 18px; }
.branch-search, .branch-region-select {
  min-height: 44px;
  padding: 10px 14px;
  border: 1px solid $(border.color);
  border-radius: 6px;
  background: #fff;
  font-size: 15px;
  color: $(text.color);
}
.branch-search { flex: 1 1 260px; min-width: 0; }
.branch-region-select { flex: 0 1 200px; }
.post-body .branch-count { flex: 1 1 100%; margin: 0 !important; font-size: 14px !important; color: $(muted.color) !important; }
.branch-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 18px; }
@media (min-width: 700px) { .branch-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.branch-card { display: flex; flex-direction: column; background: #fff; border: 1px solid $(border.color); border-radius: 10px; overflow: hidden; }
.branch-card[hidden] { display: none !important; }
.branch-photo { display: block; width: 100% !important; aspect-ratio: 16 / 9; height: auto !important; object-fit: cover; margin: 0 !important; border-radius: 0 !important; }
.branch-body { display: flex; flex-direction: column; gap: 8px; padding: 18px; flex: 1 1 auto; }
.post-body .branch-region { align-self: flex-start; font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif !important; font-size: 12px !important; letter-spacing: 0.8px !important; color: $(primary.color) !important; background-color: $(band.background.color) !important; }
.post-body .branch-name { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif !important; font-size: 21px !important; color: $(primary.color) !important; margin: 0 !important; scroll-margin-top: 150px; }
.branch-details { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 4px 12px; margin: 4px 0 0; font-size: 15px; }
.branch-details dt { font-weight: 700; color: $(muted.color); font-size: 13px; text-transform: uppercase; letter-spacing: 0.5px; padding-top: 2px; }
.branch-details dd { margin: 0; overflow-wrap: anywhere; }
.post-body .branch-details a { color: $(primary.color) !important; text-decoration: none; }
.post-body .branch-notes { font-size: 14px !important; font-style: italic; color: $(muted.color) !important; margin: 0 !important; }
.branch-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: auto; padding-top: 10px; }
.post-body .branch-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 42px;
  padding: 8px 14px;
  border-radius: 6px;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif !important;
  font-size: 15px !important;
  letter-spacing: 0.5px !important;
  text-transform: uppercase;
  text-decoration: none;
  color: #fff !important;
  background: $(primary.color);
}
.post-body .branch-btn:hover { opacity: 0.9; }
.post-body .branch-call { background: $(accent.color); }
.post-body .branch-whatsapp { background: #147A3E; }
.post-body .branch-map { background: #fff; color: $(primary.color) !important; box-shadow: inset 0 0 0 2px $(border.color); }
.branch-btn .social-icon { width: 16px; height: 16px; }
@media (max-width: 479px) { .post-body .branch-btn { flex: 1 1 calc(50% - 4px); justify-content: center; } }

/* ---------- Videos under short articles ---------- */
.video-fill { margin-top: 36px; }
.video-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 18px; }
@media (min-width: 640px) { .video-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.video-card { background: #fff; border-radius: 10px; box-shadow: 0 2px 14px rgba(15, 30, 55, 0.08); overflow: hidden; }
.video-thumb, .video-frame { position: relative; display: block; width: 100%; aspect-ratio: 16 / 9; background: #000; }
.video-thumb { padding: 0; border: 0; cursor: pointer; }
.video-thumb img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0.9; transition: opacity 0.2s; }
.video-thumb:hover img { opacity: 1; }
.video-play {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 64px;
  height: 64px;
  margin: -32px 0 0 -32px;
  border-radius: 50%;
  background: $(accent.color);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
  transition: transform 0.2s;
}
.video-play::after {
  content: '';
  position: absolute;
  left: 26px;
  top: 20px;
  border-style: solid;
  border-width: 12px 0 12px 19px;
  border-color: transparent transparent transparent #fff;
}
.video-thumb:hover .video-play, .video-thumb:focus-visible .video-play { transform: scale(1.08); }
.video-frame iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }
.video-title { margin: 0; padding: 12px 16px 14px; font-weight: 700; font-size: 15px; line-height: 1.35; color: $(primary.color); }

/* ---------- HTML site map page ---------- */
.sitemap-summary { color: $(muted.color); }
.sitemap-topics { display: flex; flex-wrap: wrap; gap: 8px; margin: 0 0 8px; }
.post-body .sitemap-topics a { color: $(primary.color) !important; text-decoration: none; }
.post-body .sitemap-topics a:hover { background: $(accent.color); color: #fff !important; }
.post-body .u-sitemap h2 { scroll-margin-top: 150px; border-bottom: 2px solid $(border.color); padding-bottom: 6px; }
body .widget .post-body ul.sitemap-list { list-style: none; padding: 0; margin: 0 0 1.4em; }
@media (min-width: 768px) { body .widget .post-body ul.sitemap-list { columns: 2; column-gap: 32px; } }
body .widget .post-body .sitemap-list li { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 2px 12px; padding: 7px 0; border-bottom: 1px solid $(border.color); break-inside: avoid; }
.post-body .sitemap-list a { text-decoration: none; font-weight: 600; }
.post-body .sitemap-list time { font-size: 13px !important; color: $(muted.color) !important; white-space: nowrap; }

/* ---------- Posts area ---------- */
.page-main { padding: 44px 0 60px; }
.main-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 44px; }
/* align-items: start lets each column keep its own height, so theme.js can measure the empty space under a short article */
@media (min-width: 1024px) { .main-grid { grid-template-columns: minmax(0, 1fr) 320px; gap: 44px; align-items: start; } }
.section-head { margin-bottom: 4px; }
.post-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 22px; }
@media (min-width: 640px) { .post-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.post-card {
  display: flex;
  flex-direction: column;
  background: #ffffff;
  border-radius: 10px;
  box-shadow: 0 2px 14px rgba(15, 30, 55, 0.08);
  overflow: hidden;
  transition: transform 0.2s, box-shadow 0.2s;
}
.post-card:hover { transform: translateY(-3px); box-shadow: 0 14px 34px rgba(15, 30, 55, 0.16); }
.post-card-media { display: block; position: relative; aspect-ratio: 16 / 9; background: $(band.background.color); overflow: hidden; }
.post-card-media img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; transition: transform 0.4s; }
.post-card:hover .post-card-media img { transform: scale(1.04); }
.post-card-placeholder { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; color: $(muted.color); background: $(band.background.color); }
.post-card-body { display: flex; flex-direction: column; gap: 8px; padding: 16px 18px 18px; flex: 1 1 auto; }
.post-card-labels a:not(:first-child) { display: none; }
.post-card-title { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif; font-weight: 600; font-size: 21px; line-height: 1.25; margin: 0; color: $(primary.color); }
.post-card-title a:hover { color: $(accent.color); }
.post-card-meta { margin-top: auto; display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 13px; color: $(muted.color); }
.empty-state { background: #fff; border-radius: 10px; padding: 32px 24px; text-align: center; box-shadow: 0 2px 14px rgba(15, 30, 55, 0.08); }
.blog-pager-nav { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 12px; margin-top: 32px; }
.blog-pager-nav .older { margin-left: auto; }

/* ---------- Single post / page ---------- */
.post-single {
  background: #fff;
  border-radius: 10px;
  box-shadow: 0 2px 14px rgba(15, 30, 55, 0.08);
  padding: 22px 18px 28px;
}
@media (min-width: 768px) { .post-single { padding: 36px 44px 40px; } }
.breadcrumb { display: flex; flex-wrap: wrap; gap: 4px 8px; font-size: 13px; color: $(muted.color); margin-bottom: 14px; }
.breadcrumb a { color: $(accent.color); font-weight: 600; }
.breadcrumb a:hover { text-decoration: underline; }
.breadcrumb a + a::before { content: '\203A'; color: $(muted.color); margin-right: 8px; font-weight: 400; }
.breadcrumb .crumb-label ~ .crumb-label { display: none; }
.post-title {
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-weight: 600;
  font-size: clamp(28px, 4.4vw, 42px);
  line-height: 1.15;
  color: $(primary.color);
  margin: 0 0 14px;
}
.post-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 10px;
  font-size: 14px;
  color: $(muted.color);
  padding-bottom: 18px;
  margin-bottom: 24px;
  border-bottom: 1px solid $(border.color);
}
.post-author { font-weight: 700; color: $(primary.color); }
.post-meta .sep { width: 4px; height: 4px; border-radius: 50%; background: $(accent.color); }
.post-meta .item-control { margin-left: auto; }
.post-body { font-size: 17px; line-height: 1.75; overflow-wrap: break-word; }
.post-body a { color: $(accent.color); text-decoration: underline; text-underline-offset: 2px; }
.post-body h2, .post-body h3, .post-body h4 { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif; font-weight: 600; color: $(primary.color); margin: 1.4em 0 0.5em; }
.post-body h2 { font-size: 28px; }
.post-body h3 { font-size: 23px; }
.post-body img { border-radius: 6px; }
/* Pull quote: Blogger's "Quote" button (or any blockquote) */
.post-body blockquote {
  position: relative;
  margin: 1.8em 0;
  padding: 18px 20px 18px 30px;
  border-left: 6px solid $(accent.color);
  background: $(page.background.color);
  border-radius: 0 6px 6px 0;
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-size: 23px;
  font-style: normal;
  font-weight: 500;
  line-height: 1.4;
  color: $(primary.color);
}
.post-body blockquote::before {
  content: '\201C';
  position: absolute;
  top: -18px;
  right: 14px;
  font-family: Georgia, serif;
  font-size: 96px;
  line-height: 1;
  color: $(accent.color);
  opacity: 0.25;
}
@media (max-width: 639px) { .post-body blockquote { font-size: 20px; padding-left: 22px; } }
/* Data tables scroll sideways on phones; Blogger's image-caption tables are left alone */
.post-body table:not(.tr-caption-container) { width: 100%; border-collapse: collapse; margin: 1.2em 0; display: block; overflow-x: auto; }
.post-body table:not(.tr-caption-container) th, .post-body table:not(.tr-caption-container) td { border: 1px solid $(border.color); padding: 8px 10px; text-align: left; }
.post-body table:not(.tr-caption-container) th { background: $(band.background.color); }
.post-body iframe { display: block; margin: 1em auto; border: 0; }
/* Videos and maps pasted into posts keep their shape on every screen (Blogger gives them a fixed width/height) */
.post-body iframe[src*='youtube'], .post-body iframe[src*='youtu.be'], .post-body iframe[src*='vimeo'],
.post-body iframe[src*='facebook.com/plugins/video'], .post-body iframe[src*='dailymotion'],
.post-body .YOUTUBE-iframe-video, .post-body iframe.b-hbp-video {
  width: 100% !important;
  height: auto !important;
  aspect-ratio: 16 / 9;
}
.post-body iframe[src*='google.com/maps'] { width: 100% !important; aspect-ratio: 4 / 3; height: auto !important; }
.post-body video { width: 100%; height: auto; }
.post-body pre, .post-body code { white-space: pre-wrap; overflow-wrap: anywhere; }
.post-body pre { overflow-x: auto; background: $(page.background.color); padding: 12px 14px; border-radius: 6px; font-size: 14px; }
.post-body .tr-caption-container { max-width: 100%; }
.post-body .tr-caption { font-size: 13px; color: $(muted.color); }
.post-tags { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 30px; }
.post-tags-label, .u-share-label { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif; font-size: 14px; letter-spacing: 0.6px; text-transform: uppercase; color: $(muted.color); margin-right: 4px; }
.u-share { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 12px; margin-top: 24px; padding: 16px 0; border-top: 1px solid $(border.color); border-bottom: 1px solid $(border.color); }
.u-share-list { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; position: static; background: none; box-shadow: none; min-width: 0; padding: 0; margin: 0; }
.u-share-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 40px;
  height: 40px;
  padding: 0 11px;
  border: 0;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  color: #fff;
  background: $(primary.color);
  cursor: pointer;
  transition: transform 0.15s, opacity 0.15s;
}
.u-share-btn .social-icon { width: 18px; height: 18px; }
.u-share-btn:hover { transform: translateY(-2px); opacity: 0.9; color: #fff; }
.u-share-whatsapp { background: #1E8E4E; }
.u-share-facebook { background: #1877F2; }
.u-share-x { background: #111111; }
.u-share-linkedin { background: #0A66C2; }
.u-share-telegram { background: #229ED9; }
.u-share-reddit { background: #FF4500; }
.u-share-pinterest { background: #E60023; }
.u-share-email { background: #5B6778; }
.u-share-native { background: $(primary.color); }
.u-share-copy, .u-share-print { background: $(band.background.color); color: $(primary.color); padding: 0 16px; }
.u-share-copy:hover, .u-share-print:hover { color: $(primary.color); }
.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
.print-source { display: none; }
.join-box {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-top: 28px;
  padding: 22px;
  border-radius: 10px;
  background: $(primary.color);
  color: #D5DDE8;
  border-left: 6px solid $(accent.color);
}
.join-box p { margin: 0; }
.join-box-title { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif; font-size: 22px; font-weight: 600; text-transform: uppercase; color: #fff; margin-bottom: 4px !important; }
@media (min-width: 640px) { .join-box { flex-direction: row; align-items: center; justify-content: space-between; } .join-box .btn { flex: 0 0 auto; } }
.related { margin-top: 36px; }
.related-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; }
@media (min-width: 640px) { .related-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.related-grid .feed-card .feed-title { font-size: 15px; }

/* Blogger's comment markup */
.comments { margin-top: 40px; }
.comments h4, #comments h4 {
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-weight: 600;
  font-size: 24px;
  text-transform: uppercase;
  color: $(primary.color);
  margin: 0 0 16px;
}
.comments .comments-content .comment-thread ol { list-style: none; margin: 0; padding: 0; }
.comments .comment-block { margin-left: 52px; }
.comments .avatar-image-container { float: left; width: 40px; height: 40px; max-height: 40px; border-radius: 50%; overflow: hidden; }
.comments .avatar-image-container img { width: 40px; height: 40px; max-width: 40px; }
.comments .comments-content .comment { margin: 0 0 16px; padding: 0; }
.comments .comments-content .comment-content { background: $(page.background.color); padding: 12px 14px; border-radius: 6px; margin: 6px 0; line-height: 1.6; }
.comments .comments-content .user { font-weight: 700; color: $(primary.color); }
.comments .comments-content .datetime { font-size: 12px; color: $(muted.color); margin-left: 8px; }
.comments .comment-actions a, .comments .continue a, .comment-footer a { font-size: 13px; font-weight: 700; color: $(accent.color); margin-right: 10px; }
.comments .comments-content .comment-replies { margin-left: 52px; }
.comments .comments-content .icon.blog-author { display: inline-block; width: 14px; height: 14px; margin-left: 4px; border-radius: 50%; background: $(accent.color); vertical-align: -2px; }
#comment-editor, .comment-form iframe { width: 100% !important; }
.comment-form { max-width: 100%; }

/* 404 */
.not-found { background: #fff; border-radius: 10px; box-shadow: 0 2px 14px rgba(15, 30, 55, 0.08); padding: 44px 22px; text-align: center; }
.not-found-code { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif; font-weight: 700; font-size: 96px; line-height: 1; color: $(accent.color); margin: 0 0 8px; }
.not-found h1 { font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif; font-size: 32px; text-transform: uppercase; color: $(primary.color); }
.not-found p { color: $(muted.color); max-width: 460px; margin: 0 auto 20px; }
.not-found .search-form { max-width: 420px; margin: 0 auto 20px; }
.not-found .search-form input { padding: 10px 16px; }

/* ---------- Sidebar ---------- */
.sidebar .widget {
  background: #fff;
  border-radius: 10px;
  box-shadow: 0 2px 14px rgba(15, 30, 55, 0.08);
  padding: 20px 20px 22px;
  margin-bottom: 24px;
}
.sidebar .widget > h2,
.sidebar .widget h2.title {
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-weight: 600;
  font-size: 19px;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: $(primary.color);
  margin: 0 0 14px;
  padding-bottom: 10px;
  border-bottom: 2px solid $(border.color);
  position: relative;
}
.sidebar .widget > h2::after,
.sidebar .widget h2.title::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: -2px;
  width: 40px;
  height: 2px;
  background: $(accent.color);
}
.sidebar .widget-content { font-size: 15px; }
.sidebar .widget:empty { display: none; }
.join-card { text-align: left; }
.join-card p { color: $(muted.color); }
.join-card a { width: 100%; }
.sidebar .HTML form { text-align: center; }
.sidebar .HTML input[type='image'] { max-width: 100%; height: auto; }
.video-embed, .map-embed { position: relative; aspect-ratio: 16 / 9; border-radius: 6px; overflow: hidden; background: $(band.background.color); }
.map-embed { aspect-ratio: 4 / 3; }
.video-embed iframe, .map-embed iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }
.fb-page-embed { display: flex; justify-content: center; }
.fb-page-embed iframe { width: 100%; max-width: 340px; }
.popular-posts ul li { padding: 10px 0 !important; border-top: 1px solid $(border.color); }
.popular-posts ul li:first-child { border-top: 0; padding-top: 0 !important; }
.popular-posts .item-content, .popular-posts .item-thumbnail-only { display: flex; gap: 12px; align-items: flex-start; }
.popular-posts .item-thumbnail { flex: 0 0 64px; float: none; margin: 0; }
.popular-posts .item-thumbnail img { width: 64px; height: 64px; object-fit: cover; border-radius: 6px; padding: 0; }
.popular-posts .item-title { font-weight: 700; font-size: 14px; line-height: 1.35; color: $(primary.color); padding: 0; }
.popular-posts .item-title a:hover { color: $(accent.color); }
.popular-posts .item-snippet { font-size: 13px; color: $(muted.color); }
.popular-posts div[style] { display: none; }
.sidebar .list-label-widget-content ul { display: flex; flex-wrap: wrap; gap: 8px; }
.sidebar .list-label-widget-content li a,
.sidebar .list-label-widget-content li span {
  display: inline-block;
  padding: 6px 12px;
  border-radius: 999px;
  background: $(page.background.color);
  border: 1px solid $(border.color);
  font-size: 13px;
  font-weight: 600;
  color: $(primary.color);
  transition: background 0.2s, color 0.2s, border-color 0.2s;
}
.sidebar .list-label-widget-content li a:hover { background: $(accent.color); border-color: $(accent.color); color: #fff; }
.sidebar .list-label-widget-content li span[dir] { background: $(primary.color); color: #fff; }

/* ---------- Footer ---------- */
.site-footer {
  position: relative;
  background: $(primary.dark.color);
  color: #9AA8BC;
  font-size: 15px;
  border-top: 6px solid $(accent.color);
}
.footer-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 34px; padding: 52px 0 36px; }
@media (min-width: 640px) { .footer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1024px) { .footer-grid { grid-template-columns: 1.3fr 1fr 1.2fr 1fr; gap: 40px; } }
.site-footer .widget { margin-bottom: 26px; }
.site-footer .widget:last-child { margin-bottom: 0; }
.site-footer .widget > h2,
.site-footer h2.title {
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif;
  font-weight: 600;
  font-size: 18px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #fff;
  margin: 0 0 16px;
}
.site-footer .widget > h2::after,
.site-footer h2.title::after { content: ''; display: block; width: 32px; height: 3px; background: $(accent.color); margin-top: 8px; }
.site-footer a { color: #D5DDE8; }
.site-footer a:hover { color: #fff; }
.site-footer strong { color: #fff; }
.site-footer .widget-content ul li { padding: 5px 0; }
.site-footer .list-label-widget-content li a::before { content: '\203A'; color: $(accent.color); margin-right: 8px; font-weight: 700; }
.contact-list li { padding: 4px 0 !important; }
.logo-list-small { justify-content: flex-start; gap: 14px; }
.site-footer .logo-list img { filter: none; opacity: 1; max-height: 70px; background: #fff; padding: 6px; border-radius: 6px; }
#google_translate_element select { max-width: 100%; padding: 6px; border-radius: 6px; border: 0; color: $(text.color); }
.footer-bottom {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 18px 0 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  font-size: 13px;
  text-align: center;
}
.footer-bottom p { margin: 0; }
.footer-social { display: flex; flex-wrap: wrap; justify-content: center; gap: 4px; }
/* Certifications & accreditations strip at the top of the footer */
.footer-certs { padding: 40px 0 34px; border-bottom: 1px solid rgba(255, 255, 255, 0.1); text-align: center; }
.footer-certs .widget > h2, .footer-certs h2.title { display: inline-block; }
.footer-certs h2.title::after { margin-left: auto; margin-right: auto; }
.cert-list { display: flex; flex-wrap: wrap; justify-content: center; gap: 16px; }
body .cert-list li {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  width: 140px;
  padding: 0;
}
.cert-list img, .cert-list .logo-placeholder {
  display: block;
  width: 120px;
  height: 90px;
  object-fit: contain;
  padding: 8px;
  background: #fff;
  border-radius: 6px;
}
.cert-list .logo-placeholder { border: 2px dashed rgba(19, 41, 75, 0.35); font-size: 11px; line-height: 1.3; text-align: center; }
.cert-list li > span:not(.logo-placeholder), .cert-list li > a > span { font-size: 12px; line-height: 1.35; color: #D5DDE8; }
@media (max-width: 479px) {
  body .cert-list li { width: calc(50% - 8px); }
  .cert-list img, .cert-list .logo-placeholder { width: 100%; }
}
/* "Powered by Blogger" is hidden; the gadget stays so Blogger doesn't re-add it */
.footer-credit, .Attribution { display: none !important; }
@media (min-width: 900px) {
  .footer-bottom { flex-direction: row; justify-content: space-between; text-align: left; }
}
.to-top {
  position: fixed;
  right: 16px;
  right: max(16px, env(safe-area-inset-right));
  bottom: 16px;
  bottom: max(16px, env(safe-area-inset-bottom));
  z-index: 90;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: $(accent.color);
  color: #fff !important;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 14px 34px rgba(15, 30, 55, 0.16);
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: opacity 0.2s, transform 0.2s, visibility 0.2s;
}
.to-top.is-visible { opacity: 1; visibility: visible; transform: translateY(0); }
.to-top:hover { background: $(accent.dark.color); }

/* ---------- Phones: centre short content ---------- */
@media (max-width: 959px) {
  .hero-copy { text-align: center; }
  .hero-text { margin: 0 auto; }
  .hero-eyebrow::before { display: none; }
  .hero-actions ul { justify-content: center; }
}
@media (max-width: 639px) {
  .topbar-search { flex: 1 1 auto; max-width: 46%; }
  .lang-current { font-size: 0; }
  .lang-current::before { content: attr(data-short); font-size: 13px; }
  .topbar-social .widget-content a { width: 30px; height: 30px; }
  .brand-logo img { max-height: 48px; }
  .hero-actions li { flex: 1 1 100%; }
  .hero-actions li a { width: 100%; }
  .cta-body li { flex: 1 1 100%; }
  .cta-body li a { width: 100%; }
  .band-services .widget-content li { text-align: center; }
  .feed-head { flex-wrap: wrap; }
  .blog-pager-nav .btn { flex: 1 1 100%; }
  .post-body .separator a { float: none !important; margin-left: 0 !important; margin-right: 0 !important; }
  .site-footer { text-align: center; }
  .site-footer .widget > h2::after, .site-footer h2.title::after { margin-left: auto; margin-right: auto; }
  .logo-list-small { justify-content: center; }
}

@media (max-width: 479px) {
  .topbar-inner { flex-wrap: wrap; gap: 6px 10px; padding-top: 5px; padding-bottom: 8px; }
  .topbar-search { order: 3; flex: 1 1 100%; max-width: none; }
  .u-share-copy, .u-share-print { flex: 1 1 calc(50% - 4px); }
}

/* ---------- Responsive extras ---------- */
/* Long words, URLs and names never push the page sideways */
.hero-title, .post-title, .post-card-title, .feed-title, .section-title, .cta-title,
.brand-name, .band h2.title, .sidebar h2, .site-footer h2, .site-footer .widget-content { overflow-wrap: break-word; }
.post-body { overflow-wrap: anywhere; }
/* ...but data tables keep whole words and scroll sideways instead of squashing to one letter per line */
.post-body table:not(.tr-caption-container) { overflow-wrap: normal; -webkit-overflow-scrolling: touch; }
.post-body table:not(.tr-caption-container) th,
.post-body table:not(.tr-caption-container) td { overflow-wrap: normal; word-break: normal; min-width: 4.5em; }
.post-body img { max-width: 100% !important; height: auto !important; }
.post-body .tr-caption-container { max-width: 100%; height: auto !important; }
.post-body .tr-caption-container td { padding: 0; }
/* Very small phones (fold-style, 280-340px) */
@media (max-width: 340px) {
  .container { padding: 0 12px; }
  .hero-title { font-size: 28px; }
  .brand-name { font-size: 17px; }
  .brand-mark { flex-basis: 40px; width: 40px; height: 40px; font-size: 15px; }
  .nav-toggle { width: 42px; height: 42px; }
  .topbar-social .widget-content a { width: 28px; height: 28px; }
  .lang-toggle { padding: 0 9px; }
  .post-single { padding: 18px 14px 22px; }
  .band { padding: 40px 0; }
  .feed-strip > li { flex-basis: 84%; }
  .feed-tiles { grid-template-columns: minmax(0, 1fr); }
}
/* Phones held sideways: a slimmer sticky header leaves room to read */
@media (max-height: 520px) and (orientation: landscape) {
  .header-inner { min-height: 56px; }
  .brand { padding: 4px 0; }
  .brand-logo img { max-height: 40px; }
  .brand-mark { flex-basis: 38px; width: 38px; height: 38px; }
  .hero-grid { padding-top: 28px; padding-bottom: 36px; }
  .hero-media { max-width: 560px; margin: 0 auto; }
}
/* Tablets: sidebar gadgets side by side under the posts */
@media (min-width: 640px) and (max-width: 1023px) {
  .sidebar-section { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 20px; align-items: start; }
}
/* Large monitors: use a little more of the width */
@media (min-width: 1600px) {
  .container { max-width: 1320px; }
  body { font-size: 17px; }
}
/* Touch screens: finger-sized tap targets (44px where space allows) */
@media (pointer: coarse) {
  .topbar-social .widget-content a, .footer-social a { width: 40px; height: 40px; }
  .lang-toggle { height: 40px; }
  .topbar-search input { min-height: 40px; }
  .topbar-search button { width: 44px; }
  .u-share-btn { min-width: 44px; height: 44px; }
  .feed-more, .breadcrumb a { display: inline-block; padding-top: 10px; padding-bottom: 10px; }
  .slide-btn { width: 44px; height: 44px; margin-top: -22px; }
  .slide-dots button { width: 28px; height: 28px; }
  .slide-dots button::before { left: 8px; top: 8px; width: 12px; height: 12px; }
  .site-footer .widget-content ul li a, .sidebar .list-label-widget-content li a { display: inline-block; padding-top: 8px; padding-bottom: 8px; }
  .lang-menu a { padding: 12px 18px; }
  .ticker-list a { display: inline-block; padding: 12px 0; }
}
@media (pointer: coarse) and (max-width: 479px) {
  .topbar-social .widget-content a { width: 38px; height: 38px; }
}
@media (pointer: coarse) and (max-width: 340px) {
  .topbar-social .widget-content a { width: 34px; height: 34px; }
}
/* Respect "reduce motion" settings */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; }
  .ticker-list { animation: none !important; }
}

/* ---------- One consistent text style, whatever was pasted in ----------
   Posts and gadgets often carry fonts, sizes and colours from Word, websites or old
   themes (Times New Roman 8px, blue Comic Sans...). The theme's style always wins;
   bold, italics, underline, alignment, quotes and links still work. In gadgets only
   unclassed elements (pasted text) are reset, so the theme's own gadget markup keeps its design. */
.post-body p,
.post-body span,
.post-body font,
.post-body div,
.post-body li,
.post-body td,
.post-body th,
.post-body a,
.post-body b,
.post-body strong,
.post-body em,
.post-body i,
.post-body u,
.post-body small,
.post-body big,
.post-body section,
.post-body article,
.post-body label,
.post-body dd,
.post-body dt,
.post-body center,
.sidebar .HTML .widget-content p:not([class]),
.sidebar .HTML .widget-content span:not([class]),
.sidebar .HTML .widget-content font:not([class]),
.sidebar .HTML .widget-content div:not([class]),
.sidebar .HTML .widget-content li:not([class]),
.sidebar .HTML .widget-content td:not([class]),
.sidebar .HTML .widget-content center:not([class]),
.site-footer .HTML .widget-content p:not([class]),
.site-footer .HTML .widget-content span:not([class]),
.site-footer .HTML .widget-content font:not([class]),
.site-footer .HTML .widget-content div:not([class]),
.site-footer .HTML .widget-content li:not([class]),
.site-footer .HTML .widget-content td:not([class]),
.site-footer .HTML .widget-content center:not([class]),
.hero-text p:not([class]),
.hero-text span:not([class]),
.hero-text font:not([class]),
.hero-text div:not([class]),
.hero-text li:not([class]),
.hero-text td:not([class]),
.hero-text center:not([class]),
.cta-body p:not([class]),
.cta-body span:not([class]),
.cta-body font:not([class]),
.cta-body div:not([class]),
.cta-body li:not([class]),
.cta-body td:not([class]),
.cta-body center:not([class]),
.band-services .widget-content p:not([class]),
.band-services .widget-content span:not([class]),
.band-services .widget-content font:not([class]),
.band-services .widget-content div:not([class]),
.band-services .widget-content li:not([class]),
.band-services .widget-content td:not([class]),
.band-services .widget-content center:not([class]),
.comments .comment-content p:not([class]),
.comments .comment-content span:not([class]),
.comments .comment-content font:not([class]),
.comments .comment-content div:not([class]),
.comments .comment-content li:not([class]),
.comments .comment-content td:not([class]),
.comments .comment-content center:not([class]) {
  font-family: inherit !important;
  font-size: inherit !important;
  line-height: inherit !important;
  letter-spacing: normal !important;
}
.post-body p,
.post-body span,
.post-body font,
.post-body div,
.post-body li,
.post-body td,
.post-body th,
.post-body b,
.post-body strong,
.post-body em,
.post-body i,
.post-body u,
.post-body small,
.post-body big,
.post-body section,
.post-body article,
.post-body label,
.post-body dd,
.post-body dt,
.post-body center,
.sidebar .HTML .widget-content p:not([class]),
.sidebar .HTML .widget-content span:not([class]),
.sidebar .HTML .widget-content font:not([class]),
.sidebar .HTML .widget-content div:not([class]),
.sidebar .HTML .widget-content li:not([class]),
.sidebar .HTML .widget-content td:not([class]),
.sidebar .HTML .widget-content center:not([class]),
.site-footer .HTML .widget-content p:not([class]),
.site-footer .HTML .widget-content span:not([class]),
.site-footer .HTML .widget-content font:not([class]),
.site-footer .HTML .widget-content div:not([class]),
.site-footer .HTML .widget-content li:not([class]),
.site-footer .HTML .widget-content td:not([class]),
.site-footer .HTML .widget-content center:not([class]),
.hero-text p:not([class]),
.hero-text span:not([class]),
.hero-text font:not([class]),
.hero-text div:not([class]),
.hero-text li:not([class]),
.hero-text td:not([class]),
.hero-text center:not([class]),
.cta-body p:not([class]),
.cta-body span:not([class]),
.cta-body font:not([class]),
.cta-body div:not([class]),
.cta-body li:not([class]),
.cta-body td:not([class]),
.cta-body center:not([class]),
.band-services .widget-content p:not([class]),
.band-services .widget-content span:not([class]),
.band-services .widget-content font:not([class]),
.band-services .widget-content div:not([class]),
.band-services .widget-content li:not([class]),
.band-services .widget-content td:not([class]),
.band-services .widget-content center:not([class]),
.comments .comment-content p:not([class]),
.comments .comment-content span:not([class]),
.comments .comment-content font:not([class]),
.comments .comment-content div:not([class]),
.comments .comment-content li:not([class]),
.comments .comment-content td:not([class]),
.comments .comment-content center:not([class]) {
  color: inherit !important;
  background-color: transparent !important;
}
.post-body a, .post-body a span, .post-body a font { color: $(accent.color) !important; }
.post-body h1, .post-body h2, .post-body h3, .post-body h4, .post-body h5, .post-body h6 {
  font-family: 'Oswald', 'Arial Narrow', Arial, sans-serif !important;
  color: $(primary.color) !important;
  line-height: 1.25 !important;
  letter-spacing: 0.2px !important;
  background: none !important;
}
.post-body h1 { font-size: 30px !important; }
.post-body h2 { font-size: 27px !important; }
.post-body h3 { font-size: 23px !important; }
.post-body h4 { font-size: 20px !important; }
.post-body h5, .post-body h6 { font-size: 18px !important; }
.post-body h1 *, .post-body h2 *, .post-body h3 *, .post-body h4 *, .post-body h5 *, .post-body h6 * { font-size: inherit !important; color: inherit !important; }
.post-body sub, .post-body sup { font-size: 0.75em !important; }
.post-body p:empty, .post-body div:empty:not(.separator) { display: none; }
@media (max-width: 639px) {
  .post-body h1 { font-size: 26px !important; }
  .post-body h2 { font-size: 24px !important; }
  .post-body h3 { font-size: 21px !important; }
}

/* ---------- Photos fit, whatever their size or shape ---------- */
.post-body img, .post-body video, .post-body svg,
.sidebar .HTML .widget-content img, .site-footer .HTML .widget-content img,
.comments .comment-content img { max-width: 100% !important; height: auto !important; }
.post-body .separator, .post-body a[imageanchor], .post-body figure { max-width: 100%; }
.post-body figure { margin: 1em 0; }
.post-body figcaption { font-size: 13px !important; color: $(muted.color) !important; text-align: center; }
/* Cards and thumbnails: photos fill the frame; logos and odd shapes are shown whole (theme.js adds .fit-contain) */
img.fit-contain { object-fit: contain !important; padding: 8px; background: #fff; }
.popular-posts img.fit-contain, .feed-list img.fit-contain { padding: 3px; }

/* ---------- Print: just the article ---------- */
@media print {
  @page { margin: 16mm 14mm; }
  html, body { background: #fff !important; color: #000; font-size: 11.5pt; }
  .topbar, .site-header, .ticker, .home-only, .sidebar, .site-footer, .to-top, .skip-link,
  .u-share, .join-box, .related, .comments, #comments, .blog-pager-nav, .breadcrumb,
  .item-control, .post-tags, .feed-block, .navbar, iframe.skiptranslate { display: none !important; }
  .page-main { padding: 0; }
  .container { max-width: none; padding: 0; }
  .main-grid { display: block; }
  .post-single { box-shadow: none; border-radius: 0; padding: 0; }
  .post-title { font-size: 22pt; color: #000; }
  .post-meta { color: #333; }
  .post-body { font-size: 11.5pt; line-height: 1.55; }
  .post-body a { color: #000; }
  .post-body a[href^='http']::after { content: ' (' attr(href) ')'; font-size: 9pt; color: #555; word-break: break-all; }
  .post-body .separator a::after, .post-body a[href$='.jpg']::after, .post-body a[href$='.png']::after { content: none; }
  .post-body img { max-width: 100% !important; height: auto !important; page-break-inside: avoid; break-inside: avoid; }
  .post-body h2, .post-body h3 { page-break-after: avoid; break-after: avoid; }
  .post-body blockquote { background: none; border-left-color: #000; }
  .print-source { display: block; margin-top: 18pt; padding-top: 8pt; border-top: 1px solid #999; font-size: 9pt; color: #444; }
}

/* ---------- Layout editor (Theme > Layout) ---------- */
body#layout .home-only,
body#layout .nav-drawer,
body#layout .footer-credit,
body#layout .u-data[hidden] { display: block !important; }
body#layout .site-header { position: static; }
body#layout .topbar-search,
body#layout .nav-toggle,
body#layout .ticker,
body#layout .to-top { display: none !important; }
body#layout .hero-grid,
body#layout .feed-row,
body#layout .leader-grid,
body#layout .main-grid,
body#layout .footer-grid { display: block; }
body#layout .header-inner { display: block; }

b:includable.script:
(function() {
  var items = ;
  var msgs = ;
  var config = ;
  // 
  var cursor = null;
  if (items && items.length > 0) {
    cursor = parseInt(items[items.length - 1].timestamp) + 1;
  }
  var bodyFromEntry = function(entry) {
    if (entry.gd$extendedProperty) {
      for (var k in entry.gd$extendedProperty) {
        if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
          return '<span class="deleted-comment">' + entry.content.$t + '</span>';
        }
      }
    }
    return entry.content.$t;
  }
  var parse = function(data) {
    cursor = null;
    var comments = [];
    if (data && data.feed && data.feed.entry) {
      for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
        var comment = {};
        // comment ID, parsed out of the original id format
        var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
        comment.id = id ? id[2] : null;
        comment.body = bodyFromEntry(entry);
        comment.timestamp = Date.parse(entry.published.$t) + '';
        if (entry.author && entry.author.constructor === Array) {
          var auth = entry.author[0];
          if (auth) {
            comment.author = {
              name: (auth.name ? auth.name.$t : undefined),
              profileUrl: (auth.uri ? auth.uri.$t : undefined),
              avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
            };
          }
        }
        if (entry.link) {
          if (entry.link[2]) {
            comment.link = comment.permalink = entry.link[2].href;
          }
          if (entry.link[3]) {
            var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
            if (pid && pid[1]) {
              comment.parentId = pid[1];
            }
          }
        }
        comment.deleteclass = 'item-control blog-admin';
        if (entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
              comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
            } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
              comment.displayTime = entry.gd$extendedProperty[k].value;
            }
          }
        }
        comments.push(comment);
      }
    }
    return comments;
  };
  var paginator = function(callback) {
    if (hasMore()) {
      var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
      if (cursor) {
        url += '&published-min=' + new Date(cursor).toISOString();
      }
      window.bloggercomments = function(data) {
        var parsed = parse(data);
        cursor = parsed.length < 50 ? null
        : parseInt(parsed[parsed.length - 1].timestamp) + 1
        callback(parsed);
        window.bloggercomments = null;
      }
      url += '&callback=bloggercomments';
      var script = document.createElement('script');
      script.type = 'text/javascript';
      script.src = url;
      document.getElementsByTagName('head')[0].appendChild(script);
    }
  };
  var hasMore = function() {
    return !!cursor;
  };
  var getMeta = function(key, comment) {
    if ('iswriter' == key) {
      var matches = !!comment.author
      && comment.author.name == config.authorName
      && comment.author.profileUrl == config.authorUrl;
      return matches ? 'true' : '';
    } else if ('deletelink' == key) {
      return config.baseUri + '/delete-comment.g?blogID='
      + config.blogId + '&postID=' + comment.id;
    } else if ('deleteclass' == key) {
      return comment.deleteclass;
    }
    return '';
  };
  var replybox = null;
  var replyUrlParts = null;
  var replyParent = undefined;
  var onReply = function(commentId, domId) {
    if (replybox == null) {
      // lazily cache replybox, and adjust to suit this style:
      replybox = document.getElementById('comment-editor');
      if (replybox != null) {
        replybox.height = '250px';
        replybox.style.display = 'block';
        replyUrlParts = replybox.src.split('#');
      }
    }
    if (replybox && (commentId !== replyParent)) {
      document.getElementById(domId).insertBefore(replybox, null);
      replybox.src = replyUrlParts[0]
      + (commentId ? '&parentID=' + commentId : '')
      + '#' + replyUrlParts[1];
      replyParent = commentId;
    }
  };
  var hash = (window.location.hash || '#').substring(1);
  var startThread, targetComment;
  if (/^comment-form_/.test(hash)) {
    startThread = hash.substring('comment-form_'.length);
  } else if (/^c[0-9]+$/.test(hash)) {
    targetComment = hash.substring(1);
  }
  // Configure commenting API:
  var configJso = {
    'maxDepth': config.maxThreadDepth
  };
  var provider = {
    'id': config.postId,
    'data': items,
    'loadNext': paginator,
    'hasMore': hasMore,
    'getMeta': getMeta,
    'onReply': onReply,
    'rendered': true,
    'initComment': targetComment,
    'initReplyThread': startThread,
    'config': configJso,
    'messages': msgs
  };
  var render = function() {
    if (window.goog && window.goog.comments) {
      var holder = document.getElementById('comment-holder');
      window.goog.comments.render(holder, provider);
    }
  };
  // render now, or queue to render when library loads:
  if (window.goog && window.goog.comments) {
    render();
  } else {
    window.goog = window.goog || {};
    window.goog.comments = window.goog.comments || {};
    window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
    window.goog.comments.loadQueue.push(render);
  }
})();
//

function googleTranslateElementInit() {
  new google.translate.TranslateElement({
    pageLanguage: '',
    autoDisplay: 'true',
    layout: google.translate.TranslateElement.InlineLayout.
  }, 'google_translate_element');
}

body.script:
//
// Solidarity theme behaviour: menu with dropdowns, hero slideshow, label news blocks,
// latest-updates ticker, related posts, social icons and small helpers. No dependencies.
(function () {
  'use strict';
  var doc = document;
  var root = doc.documentElement;

  function el(tag, attrs, children) {
    var node = doc.createElement(tag);
    if (attrs) {
      for (var k in attrs) {
        if (!attrs.hasOwnProperty(k) || attrs[k] == null) continue;
        if (k === 'text') node.textContent = attrs[k];
        else if (k === 'className') node.className = attrs[k];
        else node.setAttribute(k, attrs[k]);
      }
    }
    (children || []).forEach(function (c) { if (c) node.appendChild(c); });
    return node;
  }

  function svg(paths, size) {
    var ns = 'http://www.w3.org/2000/svg';
    var s = doc.createElementNS(ns, 'svg');
    s.setAttribute('viewBox', '0 0 24 24');
    s.setAttribute('width', size || 18);
    s.setAttribute('height', size || 18);
    s.setAttribute('aria-hidden', 'true');
    s.setAttribute('fill', 'none');
    s.setAttribute('stroke', 'currentColor');
    s.setAttribute('stroke-width', '2.4');
    s.setAttribute('stroke-linecap', 'round');
    s.setAttribute('stroke-linejoin', 'round');
    var p = doc.createElementNS(ns, 'polyline');
    p.setAttribute('points', paths);
    s.appendChild(p);
    return s;
  }
  var CHEVRON_DOWN = '6 9 12 15 18 9';
  var CHEVRON_LEFT = '15 18 9 12 15 6';
  var CHEVRON_RIGHT = '9 18 15 12 9 6';

  // ---------------------------------------------------------------- menu
  var header = doc.getElementById('site-header');
  var toggle = doc.getElementById('nav-toggle');
  var drawer = doc.getElementById('site-nav');
  var desktop = window.matchMedia ? window.matchMedia('(min-width: 1100px)') : null;

  function setMenu(open) {
    if (!header || !toggle) return;
    if (open) {
      drawer.style.top = Math.max(0, header.getBoundingClientRect().bottom) + 'px';
      header.classList.add('nav-open');
      root.classList.add('nav-locked');
    } else {
      header.classList.remove('nav-open');
